// Robust parser for Kaspersky "status of device" alerts
// Put this in an n8n Function node (returns an array of items)

// 1) Grab the inbound payload (support multiple field names)
const item = $input.first().json || {};
let body = item.text || item.textAsHtml || item.html || "";

// 2) If body contains escaped newlines like "\n", convert them to real newlines
body = body.replace(/\\n/g, "\n");

// 3) If HTML present, convert <li> to newlines before stripping tags (preserve list items)
if (/<\/?li/i.test(body)) {
  body = body
    .replace(/<li[^>]*>/gi, "\n")   // each <li> becomes a newline start
    .replace(/<\/li>/gi, "\n");     // ensure closing li also becomes newline
}

// 4) Strip remaining HTML tags, decode simple entities, normalize Unicode bullets/spaces
body = body
  .replace(/<[^>]+>/g, " ")        // remove tags
  .replace(/&nbsp;/gi, " ")        // common entity
  .replace(/\u00a0/g, " ")         // non-breaking space
  .replace(/\u2022/g, "-")         // bullet to dash
  .replace(/\r/g, "")              // strip CR
  .replace(/\t/g, " ")             // tabs to spaces
  .replace(/\s{2,}/g, " ")         // collapse whitespace
  .trim();

// 5) Use a global regex to grab each "status of device" block
// This will capture from "status of device" up to the next "status of device" or end-of-string
const blocks = [];
const blockRegex = /status of device[\s\S]*?(?=(?:status of device)|$)/gi;
let bmatch;
while ((bmatch = blockRegex.exec(body)) !== null) {
  blocks.push(bmatch[0].trim());
}

// 6) If blocks empty, as a fallback try line-based extraction that looks for lines containing "status of device"
if (blocks.length === 0) {
  const lines = body.split("\n").map(l => l.trim()).filter(Boolean);
  for (const ln of lines) {
    if (/status of device/i.test(ln)) blocks.push(ln);
  }
}

// 7) Clean each block (remove leading bullets/dashes/asterisks and join wrapped lines)
const alerts = blocks.map(bl => {
  // join internal wrapped fragments into one line
  let cleaned = bl.replace(/\n+/g, " ").replace(/\s{2,}/g, " ").trim();
  // remove any leading "- " or "*" or numbering
  cleaned = cleaned.replace(/^[-\*\s]+/g, "");
  // remove stray asterisks used for bold in text versions
  cleaned = cleaned.replace(/\*/g, "");
  return cleaned;
}).filter(Boolean);

// 8) Return as n8n items (one item per alert)
if (alerts.length === 0) {
  // helpful debug if nothing matched
  return [{ json: { error: "No alerts parsed", sample: body.slice(0, 1000) } }];
}
return alerts.map(a => ({ json: { alert: a } }));

