// Combine all alerts from previous node into one Jira ticket body

// Get all input items
const items = $input.all();

// Combine all alert lines into one formatted block
const combined = items
  .map((item, index) => `${index + 1}. ${item.json.alert}`)
  .join("\n");

// Optional: add a summary heading
const jiraDescription = `🚨 *Kaspersky Alerts Summary*\n\n${combined}`;

return [{ json: { jira_description: jiraDescription } }];

return items.filter(item => {
  const subject = (item.json.subject || "").toLowerCase();
  return (
    subject.includes("license expired") ||
    subject.includes("expires soon") ||
    subject.includes("malware scan overdue") ||
    subject.includes("protection is disabled")
  );
});
